__registry["src/lifecycle/PlatformLifecycleState.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Platform Lifecycle State Machine & Valid Transitions
 * Defines deterministic states and valid state transitions for the AgentOS platform.
 */

const PLATFORM_STATES = Object.freeze({
    STARTING: 'STARTING',
    INITIALIZING: 'INITIALIZING',
    READY: 'READY',
    DEGRADED: 'DEGRADED',
    DRAINING: 'DRAINING',
    STOPPING: 'STOPPING',
    STOPPED: 'STOPPED',
    FAILED: 'FAILED'
});

const VALID_PLATFORM_TRANSITIONS = Object.freeze({
    [PLATFORM_STATES.STARTING]: [PLATFORM_STATES.INITIALIZING, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.INITIALIZING]: [PLATFORM_STATES.READY, PLATFORM_STATES.DEGRADED, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.READY]: [PLATFORM_STATES.DEGRADED, PLATFORM_STATES.DRAINING, PLATFORM_STATES.STOPPING, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.DEGRADED]: [PLATFORM_STATES.READY, PLATFORM_STATES.DRAINING, PLATFORM_STATES.STOPPING, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.DRAINING]: [PLATFORM_STATES.STOPPING, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.STOPPING]: [PLATFORM_STATES.STOPPED, PLATFORM_STATES.FAILED],
    [PLATFORM_STATES.STOPPED]: [PLATFORM_STATES.STARTING],
    [PLATFORM_STATES.FAILED]: [PLATFORM_STATES.STARTING, PLATFORM_STATES.STOPPING, PLATFORM_STATES.STOPPED]
});

function isValidPlatformState(state) {
    return Object.values(PLATFORM_STATES).includes(state);
}

function isValidTransition(currentState, newState) {
    if (!isValidPlatformState(currentState) || !isValidPlatformState(newState)) {
        return false;
    }
    if (currentState === newState) {
        return true;
    }
    const allowed = VALID_PLATFORM_TRANSITIONS[currentState] || [];
    return allowed.includes(newState);
}

module.exports = {
    PLATFORM_STATES,
    VALID_PLATFORM_TRANSITIONS,
    isValidPlatformState,
    isValidTransition
};

};
__registry["src/lifecycle/LifecycleStore.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Platform Lifecycle State Store
 * Persists and tracks current state, history, start time, and subsystem initialization statuses.
 */

class LifecycleStore {
    constructor() {
        this.currentState = 'STOPPED';
        this.startTime = null;
        this.lastTransitionAt = null;
        this.history = [];
        this.maxHistorySize = 100;
        this.subsystems = new Map();
    }

    getState() {
        return this.currentState;
    }

    recordTransition(fromState, toState, reason = '', actor = 'system', metadata = {}) {
        const timestamp = new Date().toISOString();
        this.currentState = toState;
        this.lastTransitionAt = timestamp;
        if (toState === 'STARTING' || (toState === 'INITIALIZING' && !this.startTime)) {
            this.startTime = timestamp;
        }

        const entry = {
            id: `trans_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
            fromState,
            toState,
            reason,
            actor,
            timestamp,
            metadata
        };

        this.history.unshift(entry);
        if (this.history.length > this.maxHistorySize) {
            this.history.pop();
        }
        return entry;
    }

    setSubsystemState(name, status, details = {}) {
        this.subsystems.set(name, {
            name,
            status,
            updatedAt: new Date().toISOString(),
            details
        });
    }

    getSubsystems() {
        return Array.from(this.subsystems.values());
    }

    getHistory(limit = 50) {
        return this.history.slice(0, limit);
    }

    getUptimeSeconds() {
        if (!this.startTime) return 0;
        return Math.floor((Date.now() - new Date(this.startTime).getTime()) / 1000);
    }

    reset() {
        this.currentState = 'STOPPED';
        this.startTime = null;
        this.lastTransitionAt = null;
        this.history = [];
        this.subsystems.clear();
    }
}

module.exports = LifecycleStore;

};
__registry["src/operations/DependencyRegistry.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Dependency Registry
 * Provides a domain-agnostic registry for monitoring internal service and subsystem dependencies.
 */

class DependencyRegistry {
    constructor() {
        this.dependencies = new Map();
    }

    registerDependency(name, checkFn, metadata = {}) {
        if (!name || typeof checkFn !== 'function') {
            throw new Error('Dependency name and check function are required');
        }
        this.dependencies.set(name, {
            name,
            checkFn,
            metadata,
            lastStatus: null,
            lastCheckedAt: null,
            latency: 0,
            lastError: null
        });
    }

    unregisterDependency(name) {
        return this.dependencies.delete(name);
    }

    async checkDependency(name) {
        const dep = this.dependencies.get(name);
        if (!dep) {
            throw new Error(`Dependency '${name}' not found`);
        }
        const start = Date.now();
        try {
            const res = await dep.checkFn();
            const latency = Date.now() - start;
            dep.lastCheckedAt = new Date().toISOString();
            dep.latency = latency;
            dep.lastStatus = res.status || 'UP';
            dep.lastError = res.error || null;
            return {
                name: dep.name,
                status: dep.lastStatus,
                lastCheckedAt: dep.lastCheckedAt,
                latency: dep.latency,
                error: dep.lastError,
                details: res.details || {},
                metadata: dep.metadata
            };
        } catch (err) {
            const latency = Date.now() - start;
            dep.lastCheckedAt = new Date().toISOString();
            dep.latency = latency;
            dep.lastStatus = 'DOWN';
            dep.lastError = err.message;
            return {
                name: dep.name,
                status: 'DOWN',
                lastCheckedAt: dep.lastCheckedAt,
                latency: dep.latency,
                error: err.message,
                details: {},
                metadata: dep.metadata
            };
        }
    }

    async checkAllDependencies() {
        const results = [];
        for (const name of this.dependencies.keys()) {
            const res = await this.checkDependency(name);
            results.push(res);
        }
        return results;
    }

    getDependencyList() {
        return Array.from(this.dependencies.keys());
    }
}

const defaultDependencyRegistry = new DependencyRegistry();

module.exports = {
    DependencyRegistry,
    defaultDependencyRegistry
};

};
