        const offlineIncidents = incidents.filter(i => i.type === 'AGENT_OFFLINE' || i.type === 'HEALTH_FAILURE' || i.state === 'OPEN' || i.status === 'OPEN');
        const offlineChecks = records.filter(r => r.healthState === 'OFFLINE' || r.success === false);
