            tenantId: tid,
            sourceAgentId,
            targetAgentId,
            relationshipType,
            direction: payload.direction || 'OUTGOING',
            criticality,
            confidence,
            status,
            origin,
            metadata: payload.metadata || {},
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
