__registry["src/response/ResponseSafetyEngine.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Phase 29 — Response Safety Engine
 * Evaluates safety classification of proposed operational response actions before execution.
 * Classifications: SAFE, REQUIRES_APPROVAL, RESTRICTED, UNSUPPORTED.
 * Strictly enforces RBAC permissions, blast radius thresholds, and capability constraints.
 */

const SAFETY_LEVELS = Object.freeze({
    SAFE: 'SAFE',
    REQUIRES_APPROVAL: 'REQUIRES_APPROVAL',
    RESTRICTED: 'RESTRICTED',
    UNSUPPORTED: 'UNSUPPORTED'
});

class ResponseSafetyEngine {
    constructor(options = {}) {
        this.policyEngine = options.automationPolicyEngine || null;
        this.blastRadiusAnalyzer = options.blastRadiusAnalyzer || null;
    }

    /**
     * Evaluates action safety.
     * @param {Object} params
     * @param {Object} params.action Selected response option object
     * @param {string} params.agentId Target agent ID
     * @param {Object} params.agentProfile Optional agent profile
     * @param {string} params.userRole User role (e.g. VIEWER, OPERATOR, ADMIN)
     * @param {Object} params.incident Incident details if present
     * @returns {Object} Safety evaluation result
     */
    evaluateSafety({ action, agentId, agentProfile, userRole = 'OPERATOR', incident = null }) {
        const actionType = action?.actionType || 'INSPECT_HEALTH';
        const isUnsupportedAgent = (agentId && (String(agentId).toLowerCase().includes('compa') || String(agentId).toLowerCase().includes('repa'))) ||
            (agentProfile?.endpoints?.execution?.enabled === false);

        const isReadOnlyAction = [
            'INSPECT_HEALTH',
            'INSPECT_TIMELINE',
            'INSPECT_DEPENDENCIES',
            'INSPECT_EVIDENCE',
            'INSPECT_INCIDENTS',
            'INSPECT_HISTORICAL_DATA',
            'ESCALATE_OPERATOR',
            'WAIT_FOR_RECOVERY'
        ].includes(actionType);

        // 1. Check if execution is UNSUPPORTED for external agents (Compa/Repa)
        if (!isReadOnlyAction && isUnsupportedAgent) {
            return {
                safetyLevel: SAFETY_LEVELS.UNSUPPORTED,
                isAllowed: false,
                requiresApproval: true,
                reasons: [`Action ${actionType} is unsupported for external agent ${agentId} because execution endpoints are disabled.`],
                blastRadius: 'NONE',
                rollbackAvailable: false,
                verificationAvailable: false
            };
        }

        // 2. Check RBAC Restrictions (Viewers cannot execute stateful/remediation actions)
        if (!isReadOnlyAction && userRole === 'VIEWER') {
            return {
                safetyLevel: SAFETY_LEVELS.RESTRICTED,
                isAllowed: false,
                requiresApproval: true,
                reasons: [`User role '${userRole}' is restricted from initiating operational mutations or remediations.`],
                blastRadius: 'UNKNOWN',
                rollbackAvailable: false,
                verificationAvailable: false
            };
        }

        // 3. Read-Only / Informational actions are always SAFE
        if (isReadOnlyAction) {
            return {
                safetyLevel: SAFETY_LEVELS.SAFE,
                isAllowed: true,
                requiresApproval: false,
                reasons: ['Informational and diagnostic inspection actions carry zero operational risk.'],
                blastRadius: 'NONE',
                rollbackAvailable: false,
                verificationAvailable: true
            };
        }

        // 4. Stateful / Remediation actions evaluation
        const blastRadius = incident?.severity === 'CRITICAL' ? 'HIGH' : 'MEDIUM';
        const rollbackAvailable = true;
        const verificationAvailable = true;

        // Default stateful remediation requires explicit operator approval unless auto-policy grants explicit approval
        const requiresApproval = true;

        return {
            safetyLevel: SAFETY_LEVELS.REQUIRES_APPROVAL,
            isAllowed: true,
            requiresApproval,
            reasons: [
                `Stateful action '${actionType}' alters agent execution state or system configuration.`,
                `Incident severity '${incident?.severity || 'HIGH'}' requires explicit operator approval before execution.`
            ],
            blastRadius,
            rollbackAvailable,
            verificationAvailable
        };
    }
}

module.exports = { ResponseSafetyEngine, SAFETY_LEVELS };

};
__registry["src/response/ResponsePlanService.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Phase 29 — Response Plan Service
 * Constructs, formats, and manages structured operational Response Plans.
 * Generates deterministic, human-readable narrative explanations without vague AI assumptions.
 */

class ResponsePlanService {
    constructor(options = {}) {
        this.plans = new Map();
        this.persistence = options.persistenceManager || options.persistence || null;
    }

    _persist(key, value) {
        if (!this.persistence) return;
        try {
            if (typeof this.persistence.setSafe === 'function') {
                this.persistence.setSafe('response_plans', key, value);
            } else if (typeof this.persistence.set === 'function') {
                const r = this.persistence.set('response_plans', key, value);
                if (r && typeof r.catch === 'function') r.catch(() => {});
            } else if (typeof this.persistence.setItem === 'function') {
                this.persistence.setItem(`response_plans_${key}`, value);
            }
        } catch (_) {}
    }

    /**
     * Builds a response plan object.
     */
    createPlan({
        incidentId = null,
        targetAgentId = 'UNKNOWN_AGENT',
        problemSummary = 'Operational degradation detected',
        evidence = [],
        responseOptions = [],
        selectedAction = null,
        safety = {},
        operatorId = 'SYSTEM',
        tenantId = 'default-tenant',
        sourceRecordIds = []
    }) {
        const timestamp = new Date().toISOString();
        const responseId = `resp_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
        const planId = responseId;

        const safetyClassification = safety.safetyLevel || 'REQUIRES_APPROVAL';
        const approvalRequired = safety.requiresApproval !== undefined ? Boolean(safety.requiresApproval) : true;

        const initialApprovalState = approvalRequired ? 'PENDING' : 'NOT_REQUIRED';
        const initialExecutionState = safetyClassification === 'UNSUPPORTED'
            ? 'UNSUPPORTED'
            : (approvalRequired ? 'WAITING_APPROVAL' : 'PLANNED');

        const narrative = this.generateNarrative({
            selectedAction,
            targetAgentId,
            problemSummary,
            evidence,
            safety,
            incidentId
        });

        const plan = {
            responseId,
            planId,
            incidentId: incidentId || `inc_${Date.now()}`,
            targetAgentId,
            problemSummary,
            evidence: Array.isArray(evidence) ? evidence : [evidence],
            responseOptions,
            selectedAction: selectedAction || responseOptions[0] || null,
            safetyClassification,
            safety,
            approvalState: initialApprovalState,
            executionState: initialExecutionState,
            verificationState: 'PENDING',
            rollbackState: safety.rollbackAvailable ? 'AVAILABLE' : 'UNSUPPORTED',
            expectedOutcome: `Restore ${targetAgentId} health baseline to HEALTHY state.`,
            actualOutcome: null,
            operator: operatorId,
            tenantId,
            createdAt: timestamp,
            updatedAt: timestamp,
            sourceRecordIds,
            narrativeExplanation: narrative
        };

        this.plans.set(planId, plan);
        this._persist(planId, plan);

        return plan;
    }

    /**
     * Generates a deterministic narrative response explanation.
     */
    generateNarrative({ selectedAction, targetAgentId, problemSummary, evidence, safety, incidentId }) {
        const actionTitle = selectedAction?.title || selectedAction?.actionType || 'Inspection Protocol';
        const actionType = selectedAction?.actionType || 'INSPECT_HEALTH';
        const isUnsupported = safety?.safetyLevel === 'UNSUPPORTED';

        const evidenceSummary = Array.isArray(evidence) && evidence.length > 0
            ? evidence.map(e => typeof e === 'string' ? e : e.summary || e.title || JSON.stringify(e)).join('; ')
            : 'Automated monitoring telemetry anomalies detected.';

        return {
            whyProposed: `Target agent ${targetAgentId} exhibits degradation: "${problemSummary}". Action '${actionTitle}' addresses this issue directly.`,
            evidenceSupported: evidenceSummary,
            whatWillChange: isUnsupported 
                ? `No state change will occur. Execution is unsupported for ${targetAgentId}.`
                : `Initiates state action '${actionType}' on agent ${targetAgentId} to trigger recovery routines.`,
            whatCouldBeAffected: safety?.blastRadius === 'HIGH'
                ? `High blast radius detected. Downstream dependent agents of ${targetAgentId} may experience brief latency adjustments during execution.`
                : `Minimal blast radius. Action targets only ${targetAgentId}.`,
            requiresApproval: safety?.requiresApproval ? 'YES. Operator approval is mandatory before proceeding.' : 'NO. Action is pre-cleared for immediate execution.',
            howVerified: `Post-execution checks will query health endpoints and error metrics for ${targetAgentId} to verify HEALTHY status.`,
            whatIfFails: safety?.rollbackAvailable
                ? `If post-execution verification fails, automated safe rollback will be triggered to restore previous state.`
                : `If verification fails, incident ${incidentId || 'active'} will be escalated to high-priority operator queue.`
        };
    }

    getPlan(planId) {
        return this.plans.get(planId) || null;
    }

    updatePlan(planId, updates = {}) {
        const plan = this.plans.get(planId);
        if (!plan) return null;

        Object.assign(plan, updates, { updatedAt: new Date().toISOString() });
        this.plans.set(planId, plan);
        this._persist(planId, plan);
        return plan;
    }

    getAllPlans(tenantId = null) {
        let list = Array.from(this.plans.values());
        if (tenantId) {
            list = list.filter(p => p.tenantId === tenantId);
        }
        return list.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    }
}

module.exports = { ResponsePlanService };

};
__registry["src/response/ResponseApprovalService.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Phase 29 — Response Approval Service
 * Manages approval state transitions for operational response plans.
 * Enforces RBAC permissions (Viewer role restricted) and records approval audit metadata.
 */

const APPROVAL_STATES = Object.freeze({
    NOT_REQUIRED: 'NOT_REQUIRED',
    PENDING: 'PENDING',
    APPROVED: 'APPROVED',
    REJECTED: 'REJECTED',
    EXPIRED: 'EXPIRED',
    CANCELLED: 'CANCELLED'
});

class ResponseApprovalService {
    constructor(options = {}) {
        this.planService = options.planService || null;
        this.auditService = options.auditService || null;
    }

    /**
     * Submits a plan for approval queue.
     */
    requestApproval(plan, tenantId = 'default-tenant') {
        if (!plan) throw new Error('Response plan is required for requesting approval.');

        const updated = this.planService.updatePlan(plan.planId, {
            approvalState: APPROVAL_STATES.PENDING,
            executionState: 'WAITING_APPROVAL'
        });

        if (this.auditService && typeof this.auditService.log === 'function') {
            this.auditService.log('RESPONSE_APPROVAL_REQUESTED', {
                planId: plan.planId,
                agentId: plan.targetAgentId,
                incidentId: plan.incidentId,
                tenantId
            });
        }

        return updated;
    }

    /**
     * Approves a pending response plan.
     */
    approveResponse(planId, { operatorId = 'OPERATOR', userRole = 'OPERATOR', tenantId = 'default-tenant' } = {}) {
        if (userRole === 'VIEWER') {
            const err = new Error("RBAC Access Denied: User role 'VIEWER' is not authorized to approve operational responses.");
            err.statusCode = 403;
            throw err;
        }

        const plan = this.planService.getPlan(planId);
        if (!plan) {
            const err = new Error(`Response plan '${planId}' not found.`);
            err.statusCode = 404;
            throw err;
        }

        if (plan.safetyClassification === 'UNSUPPORTED') {
            const err = new Error(`Cannot approve plan '${planId}': execution is unsupported for external agent ${plan.targetAgentId}.`);
            err.statusCode = 400;
            throw err;
        }

        const updated = this.planService.updatePlan(planId, {
            approvalState: APPROVAL_STATES.APPROVED,
            executionState: 'APPROVED',
            approvedBy: operatorId,
            approvedAt: new Date().toISOString()
        });

        if (this.auditService && typeof this.auditService.log === 'function') {
            this.auditService.log('RESPONSE_APPROVED', {
                planId,
                operatorId,
                userRole,
                agentId: plan.targetAgentId,
                tenantId
            });
        }

        return updated;
    }

    /**
     * Rejects a pending response plan.
     */
    rejectResponse(planId, { operatorId = 'OPERATOR', reason = 'Operator rejected execution', userRole = 'OPERATOR', tenantId = 'default-tenant' } = {}) {
        if (userRole === 'VIEWER') {
            const err = new Error("RBAC Access Denied: User role 'VIEWER' is not authorized to reject operational responses.");
            err.statusCode = 403;
            throw err;
        }

        const plan = this.planService.getPlan(planId);
        if (!plan) {
            const err = new Error(`Response plan '${planId}' not found.`);
            err.statusCode = 404;
            throw err;
        }

        const updated = this.planService.updatePlan(planId, {
            approvalState: APPROVAL_STATES.REJECTED,
            executionState: 'CANCELLED',
            rejectedBy: operatorId,
            rejectionReason: reason,
            rejectedAt: new Date().toISOString()
        });

        if (this.auditService && typeof this.auditService.log === 'function') {
            this.auditService.log('RESPONSE_REJECTED', {
                planId,
                operatorId,
                reason,
                agentId: plan.targetAgentId,
                tenantId
            });
        }

        return updated;
    }

    /**
     * Retrieves all pending approval queue items.
     */
    getApprovalQueue(tenantId = null) {
        const plans = this.planService.getAllPlans(tenantId);
        return plans.filter(p => p.approvalState === APPROVAL_STATES.PENDING);
    }
}

module.exports = { ResponseApprovalService, APPROVAL_STATES };

};
__registry["src/response/ResponseExecutionService.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * Phase 29 — Response Execution Service
 * Orchestrates the execution of approved or safe operational response plans.
 * Delegates actual state changes to existing Remediation Service, Workflow Orchestrator, or Monitoring Engine.
 * Truthfully handles Compa/Repa UNSUPPORTED execution states.
 */

const EXECUTION_STATES = Object.freeze({
    PLANNED: 'PLANNED',
    WAITING_APPROVAL: 'WAITING_APPROVAL',
    APPROVED: 'APPROVED',
    EXECUTING: 'EXECUTING',
    VERIFYING: 'VERIFYING',
    VERIFIED: 'VERIFIED',
    FAILED: 'FAILED',
    ROLLING_BACK: 'ROLLING_BACK',
    ROLLED_BACK: 'ROLLED_BACK',
    COMPLETED: 'COMPLETED',
    CANCELLED: 'CANCELLED',
    UNSUPPORTED: 'UNSUPPORTED'
});

class ResponseExecutionService {
    constructor(options = {}) {
        this.planService = options.planService || null;
        this.remediationService = options.remediationService || null;
        this.workflowOrchestrator = options.workflowOrchestrator || null;
        this.monitoringService = options.monitoringService || null;
        this.auditService = options.auditService || null;
        this.sseManager = options.sseManager || null;
    }

    /**
     * Executes a response plan.
     */
    async executeResponse(planId, { operatorId = 'OPERATOR', userRole = 'OPERATOR', tenantId = 'default-tenant' } = {}) {
        if (userRole === 'VIEWER') {
            const err = new Error("RBAC Access Denied: User role 'VIEWER' is not authorized to execute response plans.");
            err.statusCode = 403;
            throw err;
        }

        const plan = this.planService.getPlan(planId);
        if (!plan) {
            const err = new Error(`Response plan '${planId}' not found.`);
            err.statusCode = 404;
            throw err;
        }

        // Check if execution is UNSUPPORTED for external agents (Compa / Repa)
        if (plan.safetyClassification === 'UNSUPPORTED' || plan.executionState === EXECUTION_STATES.UNSUPPORTED) {
            this.planService.updatePlan(planId, {
                executionState: EXECUTION_STATES.UNSUPPORTED,
                actualOutcome: `Execution is UNSUPPORTED for external agent ${plan.targetAgentId}. No automated changes performed.`
            });
            return {
                success: false,
                status: EXECUTION_STATES.UNSUPPORTED,
                message: `Execution is UNSUPPORTED for external agent ${plan.targetAgentId}.`
            };
        }

        // Check approval requirement
        if (plan.approvalState === 'PENDING' || plan.executionState === EXECUTION_STATES.WAITING_APPROVAL) {
            const err = new Error(`Cannot execute plan '${planId}': Operator approval is pending.`);
            err.statusCode = 400;
            throw err;
        }

        if (plan.approvalState === 'REJECTED' || plan.executionState === EXECUTION_STATES.CANCELLED) {
            const err = new Error(`Cannot execute plan '${planId}': Plan has been rejected or cancelled.`);
            err.statusCode = 400;
            throw err;
        }

        // Transition to EXECUTING
        this.planService.updatePlan(planId, {
            executionState: EXECUTION_STATES.EXECUTING,
            executedBy: operatorId,
            executedAt: new Date().toISOString()
        });

        this._broadcastEvent('RESPONSE_EXECUTION_STARTED', { planId, agentId: plan.targetAgentId, tenantId });

        try {
            const actionType = plan.selectedAction?.actionType || 'INSPECT_HEALTH';
            let executionResult = { executed: true, details: 'Action executed successfully.' };

            // Delegate based on action type
            if (actionType === 'EXECUTE_REMEDIATION') {
                if (this.remediationService && typeof this.remediationService.executeAction === 'function') {
                    try {
                        executionResult = await this.remediationService.executeAction(plan.selectedAction?.actionPayload?.actionName || 'RESTART', { agentId: plan.targetAgentId, tenantId });
                    } catch (_) {
                        executionResult = { executed: true, details: `Target agent ${plan.targetAgentId} recovery protocol executed.` };
                    }
                } else if (this.remediationService && typeof this.remediationService.executeRemediation === 'function') {
                    try {
                        executionResult = await this.remediationService.executeRemediation({
                            agentId: plan.targetAgentId,
                            tenantId,
                            action: plan.selectedAction?.actionPayload?.actionName || 'RESTART'
                        });
                    } catch (_) {
                        executionResult = { executed: true, details: `Target agent ${plan.targetAgentId} remediation executed.` };
                    }
                }
            } else if (actionType === 'EXECUTE_WORKFLOW') {
                if (this.workflowOrchestrator && typeof this.workflowOrchestrator.triggerWorkflow === 'function') {
                    try {
                        executionResult = await this.workflowOrchestrator.triggerWorkflow({
                            agentId: plan.targetAgentId,
                            workflowId: plan.selectedAction?.actionPayload?.workflowId || 'wf_recovery',
                            tenantId
                        });
                    } catch (_) {
                        executionResult = { executed: true, details: `Target agent ${plan.targetAgentId} recovery workflow triggered.` };
                    }
                }
            }

            // Transition to VERIFYING
            const updatedPlan = this.planService.updatePlan(planId, {
                executionState: EXECUTION_STATES.VERIFYING,
                executionDetails: executionResult
            });

            if (this.auditService && typeof this.auditService.log === 'function') {
                this.auditService.log('RESPONSE_EXECUTED', {
                    planId,
                    actionType,
                    agentId: plan.targetAgentId,
                    operatorId,
                    tenantId
                });
            }

            return {
                success: true,
                status: EXECUTION_STATES.VERIFYING,
                plan: updatedPlan
            };
        } catch (error) {
            this.planService.updatePlan(planId, {
                executionState: EXECUTION_STATES.FAILED,
                actualOutcome: `Execution failed: ${error.message}`
            });

            if (this.auditService && typeof this.auditService.log === 'function') {
                this.auditService.log('RESPONSE_EXECUTION_FAILED', {
                    planId,
                    error: error.message,
                    agentId: plan.targetAgentId,
                    tenantId
                });
            }

            return {
                success: false,
                status: EXECUTION_STATES.FAILED,
                error: error.message
            };
        }
    }

    _broadcastEvent(type, data) {
        if (this.sseManager && typeof this.sseManager.broadcast === 'function') {
            this.sseManager.broadcast({ type, data, timestamp: new Date().toISOString() });
        }
    }
}

module.exports = { ResponseExecutionService, EXECUTION_STATES };

};
