                    agentId: w.agentId,
                    tenantId,
                    warningId: w.warningId,
                    warningType: w.warningType,
                    dataClassification: 'PREDICTION',
                    evidenceLevel: 'INSUFFICIENT_DATA',
                    status: 'INSUFFICIENT_DATA',
