__registry["src/framework/AgentCapabilityRegistry.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * AgentCapabilityRegistry
 * Manages capability registration, discovery, mapping, and capability execution resolution across registered agents.
 */

class AgentCapabilityRegistry {
    constructor() {
        this.capabilities = new Map();
    }

    registerCapability(agentId, capability) {
        if (!agentId || !capability) return;
        const key = typeof capability === 'string' ? capability : (capability.name || capability.id);
        if (!key) return;

        if (!this.capabilities.has(key)) {
            this.capabilities.set(key, new Set());
        }
        this.capabilities.get(key).add(agentId);
    }

    registerAgentCapabilities(agentId, capArray = []) {
        if (!Array.isArray(capArray)) return;
        capArray.forEach(cap => this.registerCapability(agentId, cap));
    }

    findAgentsWithCapability(capabilityName) {
        if (!this.capabilities.has(capabilityName)) return [];
        return Array.from(this.capabilities.get(capabilityName));
    }

    listAllCapabilities() {
        const result = [];
        for (const [name, agents] of this.capabilities.entries()) {
            result.push({
                capability: name,
                agentCount: agents.size,
                agents: Array.from(agents)
            });
        }
        return result;
    }
}

module.exports = { AgentCapabilityRegistry };

};
__registry["src/framework/AgentToolRegistry.js"] = function(module, exports, require, __dirname, __filename) {
/**
 * AgentToolRegistry
 * Manages tool definitions exposed by framework agents or MCP tools.
 */

class AgentToolRegistry {
    constructor() {
        this.tools = new Map();
    }

    registerTool(agentId, toolData = {}) {
        const name = toolData.name || toolData.id;
        if (!agentId || !name) return;

        const toolKey = `${agentId}:${name}`;
        const toolEntry = {
            agentId,
            name,
            description: toolData.description || '',
            inputSchema: toolData.inputSchema || {},
            outputSchema: toolData.outputSchema || {},
            allowedRoles: Array.isArray(toolData.allowedRoles) ? toolData.allowedRoles : ['admin', 'operator'],
            enabled: toolData.enabled !== false,
            registeredAt: new Date().toISOString()
        };

        this.tools.set(toolKey, toolEntry);
        return toolEntry;
    }

    getTool(agentId, toolName) {
        return this.tools.get(`${agentId}:${toolName}`) || null;
    }

    listToolsForAgent(agentId) {
        const list = [];
        for (const [key, tool] of this.tools.entries()) {
            if (tool.agentId === agentId) {
                list.push(tool);
            }
        }
        return list;
    }

    listAllTools() {
        return Array.from(this.tools.values());
    }
}

module.exports = { AgentToolRegistry };

};
